import { useRef } from 'react';
import { WebView } from 'react-native-webview';
import type { Lesson, LessonEvent } from '@lessonbooks/contracts';
import { loadLessonScript, parsePlayerMessage } from './bridge';
export function LessonPreview({
  lesson,
  revision,
  onEvent,
  savesProgress = false,
}: {
  lesson: Lesson;
  revision: number;
  onEvent?: (event: LessonEvent) => void;
  savesProgress?: boolean;
}) {
  const view = useRef<WebView>(null);
  // Generated by npm run build; never generated by a model.
  // Metro requires a static require for the asset generated before native builds.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const bundle = require('../assets/player/player.json') as { html: string };
  return (
    <WebView
      ref={view}
      source={{ html: bundle.html, baseUrl: 'https://lessonbooks.invalid/' }}
      originWhitelist={['https://lessonbooks.invalid', 'about:blank']}
      javaScriptEnabled
      javaScriptCanOpenWindowsAutomatically={false}
      setSupportMultipleWindows={false}
      allowFileAccess={false}
      allowFileAccessFromFileURLs={false}
      allowUniversalAccessFromFileURLs={false}
      mixedContentMode="never"
      domStorageEnabled={false}
      cacheEnabled={false}
      onShouldStartLoadWithRequest={(request) =>
        request.url === 'about:blank' || request.url === 'https://lessonbooks.invalid/'
      }
      onMessage={(event) => {
        try {
          const parsed = parsePlayerMessage(event.nativeEvent.data, lesson.id, revision);
          if (parsed === 'ready')
            view.current?.injectJavaScript(loadLessonScript(lesson, revision, savesProgress));
          else if (parsed && onEvent) onEvent(parsed);
        } catch {
          /* Reject malformed or unrelated messages. */
        }
      }}
    />
  );
}
